ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "status": 200,
  "code": "OK",
  "response": {
    "consultPQRResponse": {
      "wSResponseHeader": {
        "system": {
          "correlationID": vars.correlationId,
          "source": "MULESOFT"
        },
        "service": {
          "status": if(payload.response.get_pqrResponse.get_pqrResult.wsResponseHeader.service.status != 'OK') 'FAIL' else 'PASS'
        }
      },
      "ocs_spcConsultar_spcPQR_spcWS_Output": {
        "error_spcCode": payload.response.get_pqrResponse.get_pqrResult.wsResponseHeader.service.status default null,
        "error_spcMessage": payload.response.get_pqrResponse.get_pqrResult.wsResponseHeader.service.statusDetail default null,
        "object_spcId": "",
        "process_spcInstance_spcId": "",
        "listOfOcsServiceRequest": payload.response.get_pqrResponse.get_pqrResult.wsResponseBody map (obj,ind) ->
          	do{var varActivity = obj.pqrActivitiesPQR filter($.pqrActivityPQR.activityName == 'AJUSTES(F12)' and $.pqrActivityPQR.activityStatus == 'En progreso')
          		---
          	"serviceRequest": {
              "contactFirstName": obj.pqrPQR.customerName,
              "customerRefNumber": obj.pqrPQR.cun,
              "ocsAccountDocumentNumber": obj.pqrPQR.identificationNumber,
              "ocsAccountDocumentType": obj.pqrPQR.documentType,
              "ocsContactDocumentNumber": obj.pqrPQR.contactDocumentNumber,
              "ocsContactDocumentType": obj.pqrPQR.contactDocumentType,
              "ocsAccountBillingNumber": obj.pqrPQR.billingAccount,
              "openedDate": obj.pqrPQR.creationDate as LocalDateTime as String {format: 'MM/dd/yyyy HH:mm:ss'},
              "srId": obj.pqrPQR.rowIdPQR,
              "srNumber": obj.pqrPQR.pqrNumber,
              "status": if (upper(obj.pqrPQR.pqrStatus) == 'CERRADO' or upper(obj.pqrPQR.pqrStatus) == 'ANULADO') 'Cerrado' else varActivity[0].pqrActivityPQR.activityStatus default "",
              "ocsAccountSegment": obj.pqrPQR.customerSegment,
              "ocsCausal": obj.pqrPQR.pqrCausal,
              "ocsSymptom": obj.pqrPQR.pqrSymptom,
              "ocsOrderNumber": obj.pqrPQR.orderNumber,
              "ocsValClaimed": obj.pqrPQR.claimedValue,
              "activity": varActivity[0].pqrActivityPQR.activityRowId,
              "technology": obj.pqrPQR.technology
            }
          },
        "siebel_spcOperation_spcObject_spcId": ""
      }
    }
}
}
